[94225] = { en="Craftsman's Writ: Rough Bronze Leggings", ai=true,
[===[Замовлення майстра: Грубі бронзові поножі]===],
[===[<У записці, написаній вицвілим чорнилом, замовлено 1 грубі бронзові поножі, а також вказано місце доставки й оплату. Унизу зазначено, що це замовлення можна передати іншому.>]===],
