[94248] = { en="Craftsman's Writ: Blue Overalls", ai=true,
[===[Замовлення майстра: Синій комбінезон]===],
[===[<У записці, написаній вицвілим чорнилом, замовлено синій комбінезон (1 шт.) і вказано місце доставки та умови оплати. Унизу зазначено, що це замовлення можна передати іншій особі.>]===],
