nil,
nil,
},
[96101] = { en="The Great Outdoors", ai=true,
[===[На лоні природи]===],
[===[Вітаю, {клас:к}. Бачу, ти маєш вигляд {стать:справжнього шукача пригод:справжньої шукачки пригод}. Це добре. Світові потрібно більше таких неспокійних душ, як ми, що шукають статків і слави.

Щоб досягти успіху в цій справі, тобі доведеться навчитися жити й процвітати в дикій природі. Не знаю, як у тебе з навичками виживання просто неба, але, мабуть, я зможу дечого тебе навчити, якщо ти {стать:готовий:готова} вчитися.

Сідай біля вогнища й влаштовуйся зручніше. Я все тобі поясню.]===],
[===[Сядьте біля Звичайного вогнища Раана й зачекайте, доки не отримаєте ефект "Посилений відпочинок".]===],
[===[Навички, потрібні для виживання просто неба, надзвичайно важливі. Шукач пригод, який добре відпочив і як слід підготувався, має значно більше шансів вижити за такого способу життя.]===],
[===[Тож тепер, коли ми засвоїли основи, чому б тобі не піти до тренерів у сусідньому селищі й не опанувати ремесло? Вони також навчать тебе створювати табірне облаштування, що пасує до твоєї нової професії.]===],
tasks = {
["Sit near the campfire"] = [===[Сісти біля вогнища]===],
["Gain the Boosted Rest buff"] = [===[Отримати ефект "Посилений відпочинок"]===],
},
},
