[96395] = { en="An Ancient Grudge", ai=true,
[===[Древня ворожнеча]===],
[===[Тан... мій могутній... тан... йому... треба... спочити.

Прошу... допоможи йому... допоможи... спочити...

Поглинутий... древньою... ворожнечею... Немає... спокою...]===],
[===[Упокойте дух Фалдріма Ковмара, а тоді поверніться до примарної служниці в залі Танів.]===],
nil,
